    self._curGiftId = checkNumber(id)
    self._clickCb = clickCb
    self._revertCb = revertCb
    self._ind = checkNumber(index)

    local data = PhoneUtils.GetPhoneGiftVo(id)
    self:FillGift(data)
    self:ActiveBtnReset(false)
end

---FillGift
---@param data PhoneGiftVo @ 礼物vo
function UIFeelingShopGiftNode:FillGift(data)
    if not data then
        return
    end
    CfUtils.FillText(self.TxtGiftName, data.name)
    CfUtils.FillImage(self.IconGift, data.photoId)

    local gradeVo = PhoneUtils.GetPhoneGiftGradeUpVo(data.id)
    if gradeVo then
        CfUtils.FillText(self.TxtNumber, "+"..checkNumber(gradeVo.addition))
        CfUtils.FillText(self.Text, gradeVo.coinAmount)
        CfUtils.FillImage(self.icon, GoodsConfMgr:GetInstance():GetPhotoPathById(gradeVo.coinId))
    end
end

